@RestController
@RequestMapping("/api/sheets/{sheetId}/people/{personId}/statements")
@Validated
public class StatementController {

    /** A statement just taken: the person as they now show, and their claims as it bound them. */
    public record TakenView(PersonView person, List<ClaimView> claims) {
    }

    /** The statement form: the day the statement is taken as of; left out, the sheet's today. */
    public record StatementForm(LocalDate asOf) {
    }

    private final StatementService service;
    private final SheetService sheets;

    public StatementController(StatementService service, SheetService sheets) {
        this.service = service;
        this.sheets = sheets;
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public TakenView take(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long personId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody(required = false) StatementForm form) {
        StatementService.Taken taken = service.take(sheetId.trim(), user.trim(), personId,
                form == null ? null : form.asOf());
        return new TakenView(PersonView.of(taken.person(), taken.summary(), sheets.today(sheetId.trim())),
                taken.claims().stream().map(ClaimView::of).toList());
    }

    /** Cancel the person's last statement. */
    @DeleteMapping("/last")
    public TakenView cancelLast(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long personId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        StatementService.Taken cancelled = service.cancelLast(sheetId.trim(), user.trim(), personId);
        return new TakenView(PersonView.of(cancelled.person(), cancelled.summary(), sheets.today(sheetId.trim())),
                cancelled.claims().stream().map(ClaimView::of).toList());
    }
}
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/sheets/{sheetId}/quick-add")
@Validated
public class QuickAddController {

    /** What a quick-add made: the person the claim is for (and whether they were added) and the claim. */
    public record QuickAddView(PersonView person, boolean personAdded, ClaimView claim) {
    }

    /** The quick-add bar: a required name, and a required amount of 0.00 or more with up to two
     *  decimals. */
    public record QuickAddForm(@NotBlank @Size(max = 200) String name,
            @NotNull @Pattern(regexp = "\\s*\\d{1,12}(\\.\\d{1,2})?\\s*") String amount) {

        BigDecimal amountValue() {
            return new BigDecimal(amount.trim()).setScale(2);
        }
    }

    private final QuickAddService service;
    private final StatementService statements;
    private final SheetService sheets;

    public QuickAddController(QuickAddService service, StatementService statements, SheetService sheets) {
        this.service = service;
        this.statements = statements;
        this.sheets = sheets;
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public QuickAddView add(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody QuickAddForm form) {
        String sheet = sheetId.trim();
        QuickAddService.Added added = service.add(sheet, user.trim(), form.name().trim(), form.amountValue());
        return new QuickAddView(PersonView.of(added.person(), statements.summary(sheet, added.person().getId()),
                sheets.today(sheet)),
                added.personAdded(), ClaimView.of(added.claim()));
    }
}

